init_prisma();
async function listNotifications(userId, query2) {
  const limit = query2.limit ?? 30;
  const prisma = getPrisma();
  const [rows, unreadCount] = await Promise.all([
    prisma.notification.findMany({
      where: {
        userId,
        ...query2.before ? { createdAt: { lt: new Date(query2.before) } } : {},
        ...query2.unread === "true" ? { readAt: null } : {}
      },
      orderBy: { createdAt: "desc" },
      take: limit + 1
    }),
    unreadNotificationCount(userId)
  ]);
  const page = rows.slice(0, limit);
  return {
    notifications: page,
    unreadCount,
    nextBefore: rows.length > limit ? page[page.length - 1].createdAt : null
  };
}
function unreadNotificationCount(userId) {
  return getPrisma().notification.count({ where: { userId, readAt: null } });
}

