      groupId: notice.groupId,
      category: "GROUP",
      title: ui((c) => c.chat.message.mentionYou, { name: notice.authorName }),
      body: bilingual(chatTexts.mentionBody, { group: notice.groupName }),
      deepLink: messageLink(notice.groupId, notice.messageId)
