async function scheduleMeeting(userId, groupId, input2, scope) {
  const scheduledAt = new Date(input2.scheduledAt);
  return runScoped(scope, async (s2) => {
    const access = await authorizeGroup(userId, groupId, "group.meetings.schedule", s2.db);
    const now = clock.now();
    const refusal = scheduleRefusal(scheduledAt, now);
    if (refusal) throw meetingError(refusal);
    const row = await s2.db.meeting.create({
      data: { groupId, scheduledAt, place: input2.place }
    });
    const when = dateParam(scheduledAt);
    await postSystemMessage(
      groupId,
      ui((c) => c.chat.system.meetingScheduled, { date: when, place: input2.place }),
      s2.effects,
      s2.db
    );
    await notifyParticipants(s2, {
      groupId,
      meetingId: row.id,
      category: "GROUP",
      title: bilingual(meetingTexts.scheduledTitle, { group: access.group.name }),
      body: bilingual(meetingTexts.scheduledBody, { date: when, place: input2.place }),
      exceptMembershipId: access.membership.id
    });
    await audit(
      { action: "meeting.scheduled", actorUserId: userId, groupId, target: `Meeting:${row.id}` },
      s2.db
    );
    const due = agendaDueAt(scheduledAt);
    s2.effects.add(
      () => dispatchJob(
        "meetings.agenda",
        { meetingId: row.id },
        { jobId: `agenda-${row.id}`, at: due.getTime() > now.getTime() ? due : now }
      )
    );
    return viewOf(s2.db, row, access.membership.id, true, now);
  });
}
