// src/modules/meetings/minutes-draft.ts
init_src();
init_texts();
var STATUS = {
  PASSED: meetingTexts.minutesVotePassed,
  REJECTED: meetingTexts.minutesVoteRejected,
  EXPIRED: meetingTexts.minutesVoteExpired
};
function list(lines, none) {
  return lines.length === 0 ? [none] : lines.map((l) => `- ${l}`);
}
function buildMinutesDraft(input2) {
  const { lang } = input2;
  const say = (text, params = {}) => bilingual(text, params)[lang];
  const section = (title) => `## ${title[lang]}`;
  const dateAndPlace = ui((c) => c.meetings.minutes.sections.dateAndPlace);
  const none = say(meetingTexts.minutesNone);
  const when = formatDateTime(input2.scheduledAt, lang);
  const copy = (select) => ui(select);
  const money4 = input2.payments.count === 0 ? [say(meetingTexts.minutesNoMoney)] : [
    say(meetingTexts.minutesMoneyLine, {
      count: input2.payments.count,
      amount: formatXAF(input2.payments.totalFcfa, lang)
    })
  ];
  const next = input2.nextMeeting ? say(meetingTexts.minutesNextMeeting, {
    date: formatDateTime(input2.nextMeeting.scheduledAt, lang),
    place: input2.nextMeeting.place
  }) : say(meetingTexts.minutesNoNextMeeting);
  const items = [
    ...input2.agendaLines.map((l) => l[lang]),
    ...input2.memberItems.map((i) => `${i.text} (${i.author})`)
  ];
  const out = [
    say(meetingTexts.minutesTitle, { date: when }),
    "",
    section(dateAndPlace),
    say(meetingTexts.dateLine, { date: when }),
    say(meetingTexts.placeLine, { place: input2.place }),
    "",
    section(copy((c) => c.meetings.minutes.sections.present)),
    ...list(input2.present, none),
    "",
    section(copy((c) => c.meetings.minutes.sections.excused)),
    ...list(input2.excused, none),
    "",
    section(copy((c) => c.meetings.minutes.sections.absent)),
    ...list(input2.absent, none),
    "",
    section(copy((c) => c.meetings.minutes.sections.items)),
    ...list(items, none),
    "",
    section(copy((c) => c.meetings.minutes.sections.money)),
    ...money4,
    "",
    section(copy((c) => c.meetings.minutes.sections.votes)),
    ...list(
      input2.votes.map(
        (v) => say(meetingTexts.minutesVoteLine, {
          title: v.title[lang],
          status: say(STATUS[v.status]),
          yes: v.yes,
          no: v.no
        })
      ),
      none
    )
  ];
  if (input2.events.length > 0) {
    out.push(
      "",
      section(meetingTexts.minutesEventsTitle),
      ...list(
        input2.events.map((e) => e[lang]),
        none
      )
    );
  }
  out.push("", section(copy((c) => c.meetings.minutes.sections.nextMeeting)), next);
  if (input2.notes) out.push("", section(meetingTexts.minutesNotes), input2.notes);
  return out.join("\n");
}

// src/modules/meetings/minutes-store.ts
init_src2();
import { z as z32 } from "zod";
var versionSchema = z32.strictObject({
  version: z32.number().int().positive(),
  text: z32.string(),
  correctionReason: z32.string().nullable(),
  /** ISO 8601 UTC. */
  publishedAt: z32.string(),
  publishedByMembershipId: z32.string().uuid(),
  hash: z32.string().regex(/^[0-9a-f]{64}$/)
});
var storeSchema = z32.strictObject({ versions: z32.array(versionSchema) });
function minutesHash(input2) {
  return sha256Hex2(canonicalJSON(input2));
}
function readVersions(stored) {
  if (!stored) return [];
  return storeSchema.parse(JSON.parse(stored)).versions;
}
function appendVersion(stored, next) {
  const versions = readVersions(stored);
  if (next.version !== versions.length + 1) {
    throw new RangeError(`minutes version ${next.version} does not follow ${versions.length}`);
  }
  return JSON.stringify({ versions: [...versions, versionSchema.parse(next)] });
}

// src/modules/meetings/meetings.minutes.ts
var partsSchema = z33.array(z33.object({ amount: z33.number().int() }));
async function paymentsIn(db, groupId, from, to) {
  const rows = await db.ledgerTransaction.findMany({
    where: { groupId, type: "PAYMENT_RECEIVED", occurredAt: { gte: from, lt: to } },
    select: { metadata: true }
  });
  const totals = rows.map((r) => {
    const parts = partsSchema.safeParse(r.metadata?.parts);
    return parts.success ? sumFcfa(parts.data.map((p) => p.amount)) : 0;
  });
  return { count: rows.length, totalFcfa: sumFcfa(totals) };
}
async function eventsIn(db, groupId, from, to) {
  const rows = await db.ledgerTransaction.findMany({
    where: { groupId, type: "EVENT", occurredAt: { gte: from, lt: to } },
    orderBy: { seq: "asc" },
    take: 40,
    select: { descriptionFr: true, descriptionEn: true, metadata: true }
  });
  return rows.filter(
    (r) => !["VOTE_CLOSED", "MINUTES_PUBLISHED"].includes(
      String(r.metadata?.event)
    )
  ).map((r) => ({ fr: r.descriptionFr, en: r.descriptionEn }));
}
async function draftInput(userId, meeting, lang, notes) {
  const prisma = getPrisma();
  const from = meeting.scheduledAt;
  const to = new Date(from.getTime() + MINUTES_WINDOW_HOURS * 36e5);
  const [members, attendance, items, payments, events, closed, next] = await Promise.all([
    prisma.membership.findMany({
      where: { groupId: meeting.groupId, status: { in: [...PARTICIPANT_STATUSES] } },
      orderBy: { createdAt: "asc" },
      select: { id: true, user: { select: { name: true } } }
    }),
    prisma.attendance.findMany({ where: { meetingId: meeting.id } }),
    prisma.agendaItem.findMany({
      where: { meetingId: meeting.id, source: "MEMBER" },
      orderBy: { createdAt: "asc" },
      select: { text: true, author: { select: { user: { select: { name: true } } } } }
    }),
    paymentsIn(prisma, meeting.groupId, from, to),
    eventsIn(prisma, meeting.groupId, from, to),
    listProposals(userId, meeting.groupId, { status: "CLOSED" }),
    prisma.meeting.findFirst({
      where: {
        groupId: meeting.groupId,
        status: "SCHEDULED",
        scheduledAt: { gt: meeting.scheduledAt }
      },
      orderBy: { scheduledAt: "asc" },
      select: { scheduledAt: true, place: true }
    })
  ]);
  const held = meeting.status === "HELD";
  const named = (status) => members.filter(
    (m) => attendanceStatus(
      attendance.find((a) => a.membershipId === m.id),
      held
    ) === status
  ).map((m) => m.user.name);
  const votes = closed.filter((v) => v.proposal.closedAt && v.proposal.closedAt >= from && v.proposal.closedAt < to).filter((v) => v.proposal.status !== "OPEN").map((v) => ({
    title: v.title,
    status: v.proposal.status,
    yes: v.proposal.yesCount,
    no: v.proposal.noCount
  }));
  return {
    lang,
    scheduledAt: meeting.scheduledAt,
    place: meeting.place,
    present: named("PRESENT"),
    excused: named("EXCUSED"),
    // Before the meeting is closed nobody is marked absent yet: those not checked in are listed as such.
    absent: [...named("ABSENT"), ...named("UNMARKED")],
    agendaLines: readGeneratedAgenda(meeting.agenda)?.items.map((i) => i.text) ?? [],
    memberItems: items.map((i) => ({ text: i.text, author: i.author?.user.name ?? "" })),
    payments,
    votes,
    events,
    nextMeeting: next,
    notes
  };
}
async function draftMinutes(userId, meetingId, notes) {
  const prisma = getPrisma();
  const { meeting } = await loadMeeting(prisma, userId, meetingId, "group.minutes.draft");
  const now = clock.now();
  const refusal = draftRefusal({ status: meeting.status, scheduledAt: meeting.scheduledAt, now });
  if (refusal) throw meetingError(refusal);
  const user = await prisma.user.findUniqueOrThrow({
    where: { id: userId },
    select: { language: true }
  });
  const text = buildMinutesDraft(await draftInput(userId, meeting, user.language, notes));
  await prisma.meeting.update({ where: { id: meetingId }, data: { minutesDraft: text } });
  return { meetingId, language: user.language, text, generatedAt: now };
}
async function publishMinutes(userId, meetingId, input2, scope) {
  return runScoped(scope, async (s2) => {
    const { meeting, access } = await loadMeeting(s2.db, userId, meetingId, "group.minutes.publish");
    const versions = readVersions(meeting.minutesPublished);
    const refusal = publishRefusal({
      status: meeting.status,
      latestText: versions.at(-1)?.text ?? null,
      text: input2.text,
      reason: input2.reason ?? null
    });
    if (refusal) throw meetingError(refusal);
    const now = clock.now();
    const version = versions.length + 1;
    const correctionReason = version === 1 ? null : input2.reason ?? null;
    const publishedAt = now.toISOString();
    const hash = minutesHash({
      meetingId,
      version,
      text: input2.text,
      correctionReason,
      publishedAt
    });
    const entry2 = {
      version,
      text: input2.text,
      correctionReason,
      publishedAt,
      publishedByMembershipId: access.membership.id,
      hash
    };
    const written = await s2.db.meeting.updateMany({
      where: { id: meetingId, minutesVersion: versions.length },
      data: {
        minutesPublished: appendVersion(meeting.minutesPublished, entry2),
        minutesVersion: version,
        publishedAt: now,
        minutesDraft: null
      }
    });
    if (written.count !== 1) throw meetingError("MINUTES_UNCHANGED");
    const day3 = dateParam(meeting.scheduledAt);
    const corrected = version > 1;
    await recordMinutesPublished(s2.db, {
      groupId: meeting.groupId,
      meetingId,
      version,
      minutesHash: hash,
      publishedByMembershipId: access.membership.id,
      occurredAt: now,
      description: corrected ? ui((c) => c.chat.system.minutesCorrected, { version, date: day3 }) : ui((c) => c.chat.system.minutesPublished, { date: day3 })
    });
    await postSystemMessage(
      meeting.groupId,
      corrected ? ui((c) => c.chat.system.minutesCorrected, { version, date: day3 }) : ui((c) => c.chat.system.minutesPublished, { date: day3 }),
      s2.effects,
      s2.db
    );
    await notifyParticipants(s2, {
      groupId: meeting.groupId,
      meetingId,
      category: "GROUP",
      title: corrected ? bilingual(meetingTexts.minutesCorrectedTitle) : bilingual(meetingTexts.minutesPublishedTitle),
      body: bilingual(meetingTexts.minutesBody, { group: access.group.name, date: day3 }),
      exceptMembershipId: access.membership.id
    });
    await audit(
      {
        action: "meeting.minutes.published",
        actorUserId: userId,
        groupId: meeting.groupId,
        target: `Meeting:${meetingId}`,
        details: { version, hash }
      },
      s2.db
    );
    const publisher = await s2.db.membership.findUniqueOrThrow({
      where: { id: access.membership.id },
      select: { id: true, user: { select: { name: true } } }
    });
    return toMinutesVersion({ ...entry2, publishedBy: publisher });
  });
}

