async function readChain(db, groupId) {
  const rows = await db.ledgerTransaction.findMany({
    where: { groupId },
    orderBy: { seq: "asc" },
    include: { postings: { select: { account: true, amount: true } } }
  });
  return rows.map((r) => ({
    id: r.id,
    groupId: r.groupId,
    seq: r.seq,
    type: r.type,
    occurredAt: r.occurredAt.toISOString(),
    roundId: r.roundId,
    membershipId: r.membershipId,
    refType: r.refType,
    refId: r.refId,
    descriptionFr: r.descriptionFr,
    descriptionEn: r.descriptionEn,
    metadata: r.metadata ?? {},
    postings: r.postings.map((p) => ({ account: p.account, amount: p.amount })),
    prevHash: r.prevHash,
    hash: r.hash
  }));
}
function headHashOf(groupId, chain) {
  return chain.at(-1)?.hash ?? genesisHash(groupId);
}

