// src/modules/statements/statements.document.ts
init_src2();
var day = (at, lang) => formatDateShort(at, lang, { withYear: true });
function rowText(line2, t) {
  const parts = [];
  const kind = t.kinds[line2.kind];
  if (kind) parts.push(kind);
  if (line2.roundNumber !== null) parts.push(`${t.round} ${line2.roundNumber}`);
  if (line2.onTime !== null) parts.push(line2.onTime ? t.onTime : t.late);
  if (line2.reversal) parts.push(`(${t.reversal})`);
  return parts.join(" \xB7 ");
}
function rowNote(line2, t, lang) {
  if (line2.feeShare !== 0) {
    return interpolate(t.feeShareNote, { amount: formatXAF(line2.feeShare, lang) });
  }
  if (line2.interest !== 0) {
    return interpolate(t.interestNote, { amount: formatXAF(line2.interest, lang) });
  }
  return null;
}
function statementDocument(data, names) {
  const lang = data.language;
  const t = statementPdfLabels[lang];
  const lastDay = new Date(Date.parse(data.period.end) - 1);
  const sections = STATEMENT_CATEGORIES.map((category) => {
    const lines = data.lines.filter((l) => l.category === category);
    return {
      title: t.sections[category],
      rows: lines.map((l) => ({
        date: day(l.at, lang),
        text: rowText(l, t),
        amount: formatXAF(l.amount, lang),
        note: rowNote(l, t, lang)
      })),
      none: lines.length === 0 ? t.none : null,
      total: formatXAF(data.totals[category], lang)
    };
  });
  const r = data.reliability;
  return {
    lang,
    title: t.title,
    header: [
      { label: t.group, value: names.groupName },
      { label: t.member, value: names.memberName },
      {
        label: t.period,
        value: `${names.periodLabel} (${day(data.period.start, lang)} \u2013 ${day(lastDay, lang)})`
      },
      {
        label: t.issued,
        value: `${day(data.issuedAt, lang)}, ${formatClock(data.issuedAt, lang)}`
      }
    ],
    amountLabel: t.amount,
    totalLabel: t.total,
    sections,
    reliability: {
      title: t.reliability,
      line: r.newMember || r.score === null ? t.reliabilityNew : interpolate(t.reliabilityScore, { score: r.score, onTime: r.onTime, due: r.due }),
      formula: interpolate(t.reliabilityFormula, { window: r.window })
    },
    footer: {
      code: `${t.verification}${lang === "fr" ? " :" : ":"} ${names.verificationCode}`,
      address: `${t.verifyAt} ${names.verifyAddress}`,
      note: t.footerNote
    }
  };
}

