// src/modules/statements/statements.pdf.ts
import PDFDocument from "pdfkit";
var LEFT = 50;
var RIGHT = 545;
var DATE_WIDTH = 72;
var AMOUNT_WIDTH = 120;
var TEXT_LEFT = LEFT + DATE_WIDTH + 6;
var AMOUNT_LEFT = RIGHT - AMOUNT_WIDTH;
var TEXT_WIDTH = AMOUNT_LEFT - TEXT_LEFT - 8;
var BODY_BOTTOM = 742;
var FOOTER_TOP = 762;
var GREY = "#555555";
var BLACK = "#000000";
var EXTRA = new Set("\u20AC\u201A\u0192\u201E\u2026\u2020\u2021\u02C6\u2030\u0160\u2039\u0152\u017D\u2018\u2019\u201C\u201D\u2022\u2013\u2014\u02DC\u2122\u0161\u203A\u0153\u017E\u0178");
function pdfText(text) {
  let out = "";
  for (const ch of text.normalize("NFC")) {
    if (ch === "\u202F") out += "\xA0";
    else if (ch === "\u2212") out += "-";
    else if (ch.codePointAt(0) <= 255 || EXTRA.has(ch)) out += ch;
    else out += "?";
  }
  return out;
}
function room(doc, height) {
  if (doc.y + height > BODY_BOTTOM) doc.addPage();
}
function amountRow(doc, row) {
  const text = pdfText(row.text);
  const height = Math.max(
    doc.heightOfString(text || " ", { width: TEXT_WIDTH }),
    doc.currentLineHeight()
  );
  room(doc, height);
  const y = doc.y;
  doc.text(pdfText(row.date), LEFT, y, { width: DATE_WIDTH, lineBreak: false });
  if (text) doc.text(text, TEXT_LEFT, y, { width: TEXT_WIDTH });
  doc.text(pdfText(row.amount), AMOUNT_LEFT, y, {
    width: AMOUNT_WIDTH,
    align: "right",
    lineBreak: false
  });
  doc.y = y + height + 2;
}
function drawSection(doc, section, totalLabel) {
  room(doc, 48);
  doc.moveDown(0.7).font("Helvetica-Bold").fontSize(11).fillColor(BLACK);
  doc.text(pdfText(section.title), LEFT, doc.y, { width: RIGHT - LEFT });
  doc.moveDown(0.2).font("Helvetica").fontSize(9);
  if (section.none) {
    doc.fillColor(GREY).text(pdfText(section.none), LEFT, doc.y, { width: RIGHT - LEFT });
    doc.fillColor(BLACK);
    return;
  }
  for (const row of section.rows) {
    amountRow(doc, row);
    if (row.note) {
      room(doc, 10);
      doc.fontSize(8).fillColor(GREY);
      doc.text(pdfText(row.note), TEXT_LEFT, doc.y - 1, { width: RIGHT - TEXT_LEFT });
      doc.fontSize(9).fillColor(BLACK);
      doc.y += 2;
    }
  }
  doc.font("Helvetica-Bold");
  amountRow(doc, { date: totalLabel, text: "", amount: section.total });
  doc.font("Helvetica");
}
function drawFooters(doc, footer) {
  const pages = doc.bufferedPageRange();
  for (let i = pages.start; i < pages.start + pages.count; i++) {
    doc.switchToPage(i);
    doc.page.margins.bottom = 0;
    doc.font("Helvetica-Bold").fontSize(8).fillColor(BLACK);
    doc.text(pdfText(footer.code), LEFT, FOOTER_TOP, { width: RIGHT - LEFT, align: "center" });
    doc.font("Helvetica");
    doc.text(pdfText(footer.address), LEFT, FOOTER_TOP + 11, {
      width: RIGHT - LEFT,
      align: "center"
    });
    doc.fillColor(GREY).fontSize(7);
    doc.text(pdfText(footer.note), LEFT, FOOTER_TOP + 23, { width: RIGHT - LEFT, align: "center" });
    doc.text(`${i + 1} / ${pages.count}`, LEFT, FOOTER_TOP + 34, {
      width: RIGHT - LEFT,
      align: "center"
    });
  }
}
function renderStatementPdf(document, issuedAt, options = {}) {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({
      size: "A4",
      margins: { top: 48, bottom: 100, left: LEFT, right: 50 },
      bufferPages: true,
      compress: options.compress ?? true,
      lang: document.lang,
      info: {
        Title: pdfText(document.title),
        Creator: "NjangiTrust",
        Producer: "NjangiTrust",
        CreationDate: issuedAt,
        ModDate: issuedAt
      }
    });
    const chunks = [];
    doc.on("data", (chunk) => chunks.push(chunk));
    doc.on("error", reject);
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.font("Helvetica-Bold").fontSize(20).fillColor(BLACK).text(pdfText(document.title), LEFT, 48);
    doc.moveDown(0.5).fontSize(10);
    for (const item of document.header) {
      const y = doc.y;
      doc.font("Helvetica-Bold").text(pdfText(item.label), LEFT, y, { width: 90, lineBreak: false });
      doc.font("Helvetica").text(pdfText(item.value), LEFT + 96, y, { width: RIGHT - LEFT - 96 });
    }
    for (const section of document.sections) drawSection(doc, section, document.totalLabel);
    room(doc, 60);
    doc.moveDown(0.9).font("Helvetica-Bold").fontSize(11);
    doc.text(pdfText(document.reliability.title), LEFT, doc.y, { width: RIGHT - LEFT });
    doc.moveDown(0.2).font("Helvetica").fontSize(9);
    doc.text(pdfText(document.reliability.line), LEFT, doc.y, { width: RIGHT - LEFT });
    doc.fillColor(GREY).fontSize(8);
    doc.text(pdfText(document.reliability.formula), LEFT, doc.y + 2, { width: RIGHT - LEFT });
    drawFooters(doc, document.footer);
    doc.end();
  });
}

// src/modules/statements/statements.period.ts
init_src();
init_src2();
init_texts();
function parseDay(value) {
  const [year, month, day3] = value.split("-").map(Number);
  const back = toDoualaLocal(fromDoualaLocal({ year, month, day: day3 }));
  if (back.year !== year || back.month !== month || back.day !== day3) {
    throw statementError("PERIOD_INVALID");
  }
  return { year, month, day: day3 };
}
function monthLabel(year, month) {
  return bilingual(statementTexts.monthPeriod, {
    month: { fr: monthNames.fr[month - 1], en: monthNames.en[month - 1] },
    year
  });
}
async function cyclePeriod(db, groupId, number, now) {
  const cycle = number ? await db.cycle.findUnique({ where: { groupId_number: { groupId, number } } }) : await db.cycle.findFirst({
    where: { groupId, startedAt: { not: null } },
    orderBy: { number: "desc" }
  });
  if (!cycle?.startedAt) throw statementError("CYCLE_NOT_FOUND");
  const { year, month, day: day3 } = toDoualaLocal(now);
  const today = { year, month, day: day3 };
  const end = cycle.closedAt?.toISOString() ?? daysPeriod(today, today).end;
  return {
    period: { start: cycle.startedAt.toISOString(), end },
    label: bilingual(statementTexts.cyclePeriod, { cycle: cycle.number })
  };
}
async function resolvePeriod(db, groupId, request2, now) {
  let resolved;
  if (request2.kind === "MONTH") {
    resolved = {
      period: monthPeriod(request2.year, request2.month),
      label: monthLabel(request2.year, request2.month)
    };
  } else if (request2.kind === "CYCLE") {
    resolved = await cyclePeriod(db, groupId, request2.number, now);
  } else {
    const period = daysPeriod(parseDay(request2.from), parseDay(request2.to));
    const lastDay = new Date(Date.parse(period.end) - 1);
    resolved = {
      period,
      label: bilingual(statementTexts.customPeriod, {
        from: {
          fr: formatDateShort(period.start, "fr", { withYear: true }),
          en: formatDateShort(period.start, "en", { withYear: true })
        },
        to: {
          fr: formatDateShort(lastDay, "fr", { withYear: true }),
          en: formatDateShort(lastDay, "en", { withYear: true })
        }
      })
    };
  }
  const refusal = validatePeriod(resolved.period);
  if (refusal) throw statementError(refusal);
  if (Date.parse(resolved.period.end) <= Date.parse(resolved.period.start)) {
    throw statementError("PERIOD_ENDS_BEFORE_START");
  }
  if (Date.parse(resolved.period.start) > now.getTime())
    throw statementError("PERIOD_IN_THE_FUTURE");
  return resolved;
}

