async function issueStatement(input2) {
  const prisma = getPrisma();
  const { period } = input2.resolved;
  const chain = await readChain(prisma, input2.groupId);
  const ledgerHeadHash = headHashOf(input2.groupId, chain);
  const existing = await prisma.statement.findFirst({
    where: {
      membershipId: input2.membershipId,
      periodStart: new Date(period.start),
      periodEnd: new Date(period.end),
      language: input2.language,
      ledgerHeadHash
    },
    orderBy: { createdAt: "desc" },
    include: withGroup
  });
  if (existing) return { statement: existing, created: false };
  const facts = await obligationFacts(prisma, input2.membershipId);
  const params = await getCurrentParams(input2.groupId, prisma);
  const data = statementData({
    groupId: input2.groupId,
    membershipId: input2.membershipId,
    language: input2.language,
    period,
    issuedAt: input2.now.toISOString(),
    lines: memberStatementLines({
      membershipId: input2.membershipId,
      transactions: chain,
      obligations: facts,
      period
    }),
    reliability: memberReliability({
      facts,
      reliabilityWindow: params.reliabilityWindow,
      now: input2.now
    })
  });
  const verificationCode = statementVerificationCode(data, ledgerHeadHash);
  const pdf = await renderStatementPdf(
    statementDocument(data, {
      groupName: input2.groupName,
      memberName: input2.memberName,
      periodLabel: input2.resolved.label[input2.language],
      verificationCode,
      verifyAddress: `${verifyHost()}/verify/${verificationCode}`
    }),
    input2.now
  );
  const fileKey = `statements/${input2.membershipId}/${newId()}.pdf`;
  await putObject(fileKey, pdf, "application/pdf");
  try {
    const statement = await prisma.statement.create({
      data: {
        createdAt: input2.now,
        membershipId: input2.membershipId,
        periodStart: new Date(period.start),
        periodEnd: new Date(period.end),
        language: input2.language,
        fileKey,
        verificationCode,
        ledgerHeadHash
      },
      include: withGroup
    });
    return { statement, created: true };
  } catch (error) {
    await getStorage().remove(fileKey).catch((cause) => log9.warn({ err: cause }, "statement file not removed"));
    throw error;
  }
}
async function createStatement(userId, request2) {
  const access = await authorizeGroup(userId, request2.groupId, "group.statements.own");
  const prisma = getPrisma();
  const now = clock.now();
  const user = await prisma.user.findUniqueOrThrow({
    where: { id: userId },
    select: { name: true, language: true }
  });
  const resolved = await resolvePeriod(prisma, request2.groupId, request2.period, now);
  const { statement } = await issueStatement({
    membershipId: access.membership.id,
    groupId: access.group.id,
    groupName: access.group.name,
    memberName: user.name,
    language: request2.language ?? user.language,
    resolved,
    now
  });
  return toStatement(statement, verifyHost());
}
async function statementCard(userId, request2) {
  const statement = await createStatement(userId, request2);
  return { type: "STATEMENT", statementId: statement.id };
}

