async function planMonthlyStatements(now = clock.now()) {
  const { year, month } = toDoualaLocal(new Date(previousMonthPeriod(now).start));
  const members = await getPrisma().membership.findMany({
    where: {
      status: { in: ["ACTIVE", "LEAVING"] },
      group: { status: "ACTIVE" },
      user: { deletedAt: null }
    },
    select: { id: true }
  });
  for (const { id } of members) {
    await dispatchJob(
      "statements.generate",
      { membershipId: id, year, month },
      { jobId: `statement-${id}-${year}-${month}` }
    );
  }
  return members.length;
}
async function generateMonthlyStatement(payload5, now = clock.now()) {
  const membership = await getPrisma().membership.findUnique({
    where: { id: payload5.membershipId },
    select: {
      id: true,
      groupId: true,
      group: { select: { name: true } },
      user: { select: { id: true, name: true, language: true, deletedAt: true } }
    }
  });
  if (!membership || membership.user.deletedAt) return false;
  const label = monthLabel(payload5.year, payload5.month);
  const { created } = await issueStatement({
    membershipId: membership.id,
    groupId: membership.groupId,
    groupName: membership.group.name,
    memberName: membership.user.name,
    language: membership.user.language,
    resolved: { period: monthPeriod(payload5.year, payload5.month), label },
    now
  });
  if (!created) return false;
  await notify([
    {
      userId: membership.user.id,
      groupId: membership.groupId,
      category: "MONEY",
      title: bilingual(statementTexts.readyTitle),
      body: bilingual(statementTexts.readyBody, { group: membership.group.name, period: label }),
      deepLink: statementsLink(membership.groupId)
    }
  ]);
  return true;
}
var registered2 = false;
function registerStatementJobs() {
  if (registered2) return;
  registered2 = true;
  registerJob({
    name: "statements.monthly",
    process: async () => {
      await planMonthlyStatements();
    }
  });
  registerJob({
    name: "statements.generate",
    process: async (job) => {
      await generateMonthlyStatement(job.data);
    }
  });
  registerRepeatable({
    id: "statements.monthly.1st",
    name: "statements.monthly",
    pattern: "0 7,13 1,2 * *"
  });
}

