async function readLedger(userId, groupId, input2) {
  await authorizeGroup(userId, groupId, "group.ledger.read");
  const where = {
    groupId,
    ...input2.before ? { seq: { lt: input2.before } } : {},
    ...input2.membershipId ? { membershipId: input2.membershipId } : {},
    ...input2.type ? { type: input2.type } : {},
    ...input2.from || input2.to ? {
      occurredAt: {
        ...input2.from ? { gte: input2.from } : {},
        ...input2.to ? { lte: input2.to } : {}
      }
    } : {}
  };
  const rows = await getPrisma().ledgerTransaction.findMany({
    where,
    orderBy: { seq: "desc" },
    take: input2.limit + 1,
    include: { postings: { select: { account: true, amount: true } } }
  });
  const hasMore = rows.length > input2.limit;
  const page = rows.slice(0, input2.limit);
  return {
    entries: page.map(
      (row) => dto({
        ...row,
        occurredAt: row.occurredAt.toISOString(),
        metadata: row.metadata ?? {},
        postings: row.postings,
        type: row.type
      })
    ),
    nextBefore: hasMore ? page.at(-1)?.seq ?? null : null
  };
}
