    await tx2.$queryRaw`SELECT "id" FROM "Group" WHERE "id" = ${owner.groupId}::uuid FOR UPDATE`;
    await tx2.$queryRaw`SELECT "id" FROM "Membership" WHERE "id" = ${owner.membershipId}::uuid FOR UPDATE`;
    await tx2.$queryRaw`SELECT "id" FROM "Loan" WHERE "id" = ${loanId}::uuid FOR UPDATE`;
