init_prisma();
init_clock();
async function openPayout(roundId, now = clock.now()) {
  return getPrisma().$transaction(async (tx2) => {
    const round = await tx2.round.findUnique({ where: { id: roundId } });
    if (!round || round.status !== "OPEN" || round.payoutAt > now || !round.beneficiaryMembershipId)
      return false;
    const changed = await tx2.round.updateMany({
      where: {
        id: round.id,
        status: "OPEN",
        payoutAt: { lte: now },
        beneficiaryMembershipId: { not: null }
      },
      data: { status: "PAYOUT" }
    });
    if (changed.count !== 1) return false;
    await settleDueDebts(tx2, {
      groupId: round.groupId,
      membershipId: round.beneficiaryMembershipId,
      roundId: round.id,
      now
    });
    return true;
  });
}
async function openDuePayouts(now = clock.now()) {
  const due = await getPrisma().round.findMany({
    where: { status: "OPEN", payoutAt: { lte: now }, beneficiaryMembershipId: { not: null } },
    select: { id: true },
    orderBy: { payoutAt: "asc" },
    take: 100
  });
  let opened = 0;
  for (const round of due) if (await openPayout(round.id, now)) opened += 1;
  return opened;
}

