var cycleError2 = defineErrors({
  CYCLE_ALREADY_STARTED: { status: 409, text: commonErrorTexts.CONFLICT },
  CYCLE_START_UNAVAILABLE: { status: 409, text: commonErrorTexts.CONFLICT }
});

// src/modules/cycles/cycles.service.ts
function describe(event) {
  switch (event.event) {
    case "CYCLE_STARTED":
      return event.mode === "FIXED" ? {
        fr: `Cycle ${event.cycleNumber} d\xE9marr\xE9. Ordre du tirage enregistr\xE9.`,
        en: `Cycle ${event.cycleNumber} started. Draw order recorded.`
      } : {
        fr: `Cycle ${event.cycleNumber} d\xE9marr\xE9 en mode ench\xE8res.`,
        en: `Cycle ${event.cycleNumber} started in bidding mode.`
      };
    default:
      return { fr: "\xC9v\xE9nement enregistr\xE9.", en: "Event recorded." };
  }
}
async function appendCycleEvent(tx2, input2) {
  await appendLedgerEntry(tx2, input2.groupId, {
    type: "EVENT",
    occurredAt: input2.occurredAt.toISOString(),
    roundId: null,
    membershipId: null,
    refType: "Cycle",
    refId: input2.refId,
    ...(() => {
      const text = describe(input2.event);
      return { descriptionFr: text.fr, descriptionEn: text.en };
    })(),
    metadata: input2.event,
    postings: []
  });
}
async function startFirstCycle(tx2, input2) {
  const group2 = await tx2.group.findUnique({
    where: { id: input2.groupId },
    select: { id: true, status: true, firstPayoutAt: true, currentCycleId: true }
  });
  if (!group2 || group2.status !== "FORMING" || group2.currentCycleId)
    throw cycleError2("CYCLE_ALREADY_STARTED");
  const active = await tx2.membership.findMany({
    where: { groupId: group2.id, status: "ACTIVE" },
    select: { id: true },
    orderBy: { id: "asc" }
  });
  if (active.length < 3 || active.length > 50) throw cycleError2("CYCLE_START_UNAVAILABLE");
  const params = await getCurrentParams(group2.id, tx2);
  const number = 1;
  const head = await ledgerHead(tx2, group2.id);
  const event = cycleStartedEvent({
    groupId: group2.id,
    cycleNumber: number,
    mode: params.rotationMode,
    latestLedgerHash: head?.hash ?? genesisHash(group2.id),
    activeMembershipIds: active.map((item) => item.id)
  });
  const now = clock.now();
  const cycle = await tx2.cycle.create({
    data: {
      groupId: group2.id,
      number,
      mode: params.rotationMode,
      firstPayoutAt: group2.firstPayoutAt,
      drawSeed: event.drawSeed,
      rotation: params.rotationMode === "FIXED" ? event.order : active.map((item) => item.id),
      startedAt: now
    }
  });
  const count = roundCount(active.length);
  const rounds = [];
  for (let index = 1; index <= count; index += 1) {
    const dates = roundDates(
      {
        firstPayoutAt: group2.firstPayoutAt,
        frequency: params.frequency,
        customPeriodMinutes: params.customPeriodMinutes,
        monthlyAnchor: params.payoutTime.monthlyAnchor
      },
      index
    );
    const row = await tx2.round.create({
      data: {
        groupId: group2.id,
        cycleId: cycle.id,
        number: index,
        beneficiaryMembershipId: params.rotationMode === "FIXED" ? event.order[index - 1] : null,
        dueAt: dates.dueAt,
        payoutAt: dates.payoutAt,
        status: index === 1 ? "OPEN" : "SCHEDULED",
        ruleSetVersion: 1
      },
      select: {
        id: true,
        number: true,
        payoutAt: true,
        dueAt: true,
        beneficiaryMembershipId: true
      }
    });
    rounds.push(row);
  }
  const first = rounds[0];
  const drafts = roundObligations({
    contributionAmount: params.contributionAmount,
    solidarityContribution: params.solidarityContribution,
    round: {
      id: first.id,
      dueAt: first.dueAt,
      beneficiaryMembershipId: first.beneficiaryMembershipId
    },
    activeMembershipIds: active.map((item) => item.id)
  });
  await tx2.obligation.createMany({
    data: drafts.map((draft) => ({
      groupId: group2.id,
      membershipId: draft.membershipId,
      kind: draft.kind,
      amount: draft.amount,
      dueAt: draft.dueAt,
      roundId: draft.roundId,
      creditorMembershipId: draft.creditorMembershipId
    }))
  });
  await tx2.group.update({
    where: { id: group2.id },
    data: { status: "ACTIVE", currentCycleId: cycle.id }
  });
  await appendCycleEvent(tx2, { groupId: group2.id, event, occurredAt: now, refId: cycle.id });
  return { cycleNumber: number, firstBeneficiaryMembershipId: event.order[0] ?? null };
}
async function openRound(roundId, now = clock.now()) {
  return getPrisma().$transaction(async (tx2) => {
    const round = await tx2.round.findUnique({
      where: { id: roundId },
      include: { cycle: { select: { mode: true } } }
    });
    if (!round || round.status !== "SCHEDULED") return false;
    const previous = round.number > 1 ? await tx2.round.findUnique({
      where: { cycleId_number: { cycleId: round.cycleId, number: round.number - 1 } },
      select: { payoutAt: true }
    }) : null;
    if (round.number > 1 && (!previous || previous.payoutAt > now)) return false;
    const claimed = await tx2.round.updateMany({
      // Opens once the previous payout is done (checked above), not at its own deadline: members
      // pay between the two.
      where: { id: roundId, status: "SCHEDULED" },
      data: { status: "OPEN" }
    });
    if (claimed.count !== 1) return false;
    const params = await getCurrentParams(round.groupId, tx2);
    const members = await tx2.membership.findMany({
      where: { groupId: round.groupId, status: { in: ["ACTIVE", "LEAVING"] } },
      select: { id: true },
      orderBy: { id: "asc" }
    });
    const drafts = roundObligations({
      contributionAmount: params.contributionAmount,
      solidarityContribution: params.solidarityContribution,
      round: {
        id: round.id,
        dueAt: round.dueAt,
        beneficiaryMembershipId: round.beneficiaryMembershipId
      },
      activeMembershipIds: members.map((member) => member.id)
    });
    await tx2.obligation.createMany({
      data: drafts.map((draft) => ({
        groupId: round.groupId,
        membershipId: draft.membershipId,
        kind: draft.kind,
        amount: draft.amount,
        dueAt: draft.dueAt,
        roundId: draft.roundId,
        creditorMembershipId: draft.creditorMembershipId
      })),
      skipDuplicates: true
    });
    return true;
  });
}
async function openDueRounds(now = clock.now()) {
  const due = await getPrisma().round.findMany({
    where: { status: "SCHEDULED" },
    select: { id: true },
    orderBy: { dueAt: "asc" },
    take: 100
  });
  let opened = 0;
  for (const round of due) if (await openRound(round.id, now)) opened += 1;
  return opened;
}
async function currentRotation(db, groupId) {
  const group2 = await db.group.findUnique({
    where: { id: groupId },
    select: { currentCycleId: true }
  });
  if (!group2?.currentCycleId) return null;
  const cycle = await db.cycle.findUniqueOrThrow({
    where: { id: group2.currentCycleId },
    select: {
      id: true,
      number: true,
      rotation: true,
      rounds: { where: { status: { not: "SCHEDULED" } }, select: { number: true } }
    }
  });
  return {
    cycleId: cycle.id,
    cycleNumber: cycle.number,
    rotation: cycle.rotation,
    currentRound: cycle.rounds.reduce((latest, round) => Math.max(latest, round.number), 0)
  };
}
async function applyRotationChange(tx2, input2) {
  await tx2.$queryRaw`SELECT "id" FROM "Group" WHERE "id" = ${input2.groupId}::uuid FOR UPDATE`;
  const current = await currentRotation(tx2, input2.groupId);
  if (!current) throw cycleError2("CYCLE_START_UNAVAILABLE");
  const cycle = await tx2.cycle.findUniqueOrThrow({
    where: { id: current.cycleId },
    select: { mode: true, rounds: { select: { id: true, number: true, status: true } } }
  });
  const same2 = input2.newOrder.length === current.rotation.length && [...input2.newOrder].sort().join() === [...current.rotation].sort().join();
  const servedKept = current.rotation.slice(0, current.currentRound).every((id, index) => input2.newOrder[index] === id);
  if (cycle.mode !== "FIXED" || !same2 || !servedKept) throw cycleError2("CYCLE_START_UNAVAILABLE");
  await tx2.cycle.update({ where: { id: current.cycleId }, data: { rotation: input2.newOrder } });
  for (const round of cycle.rounds) {
    if (round.status !== "SCHEDULED") continue;
    await tx2.round.update({
      where: { id: round.id },
      data: { beneficiaryMembershipId: input2.newOrder[round.number - 1] }
    });
  }
}

