// src/modules/cycles/cycles.governance.ts
init_src2();
init_clock();
init_rulesets2();
var DEBT_KINDS = ["BID", "FINE", "CORRECTION", "LOAN_INSTALLMENT"];
var OPEN_PAYMENT = ["CREATED", "PENDING", "EXPIRED"];
async function lockGroup2(tx2, groupId) {
  await tx2.$queryRaw`SELECT "id" FROM "Group" WHERE "id" = ${groupId}::uuid FOR UPDATE`;
}
async function currentCycle(tx2, groupId) {
  const group2 = await tx2.group.findUnique({
    where: { id: groupId },
    select: { currentCycleId: true }
  });
  if (!group2?.currentCycleId) return null;
  return tx2.cycle.findUniqueOrThrow({
    where: { id: group2.currentCycleId },
    select: {
      id: true,
      number: true,
      mode: true,
      rotation: true,
      rounds: {
        orderBy: { number: "asc" },
        select: {
          id: true,
          number: true,
          status: true,
          dueAt: true,
          payoutAt: true,
          beneficiaryMembershipId: true
        }
      }
    }
  });
}
async function applyRuleSet(tx2, input2) {
  const none = { effectiveFromRoundId: null, effectiveFromRoundNumber: null };
  await lockGroup2(tx2, input2.groupId);
  const cycle = await currentCycle(tx2, input2.groupId);
  if (!cycle) return none;
  const credited2 = await tx2.ledgerTransaction.findMany({
    where: {
      groupId: input2.groupId,
      type: { not: "EVENT" },
      roundId: { in: cycle.rounds.filter((r) => r.status === "SCHEDULED").map((r) => r.id) }
    },
    select: { roundId: true }
  });
  const withCredits = new Set(credited2.map((entry2) => entry2.roundId));
  const target = ruleChangeTargetRound(
    cycle.rounds.map((round) => ({
      number: round.number,
      opened: round.status !== "SCHEDULED",
      hasCredits: withCredits.has(round.id)
    }))
  );
  if (!target.ok || target.nextCycle) return none;
  const first = cycle.rounds.find((round) => round.number === target.roundNumber);
  const later = cycle.rounds.filter((round) => round.number >= target.roundNumber);
  await tx2.round.updateMany({
    where: { id: { in: later.map((round) => round.id) } },
    data: { ruleSetVersion: input2.version }
  });
  const { previous, next } = input2;
  const redate = previous.frequency !== next.frequency || next.frequency === "CUSTOM" && previous.customPeriodMinutes !== next.customPeriodMinutes || previous.payoutTime.hour !== next.payoutTime.hour || previous.payoutTime.minute !== next.payoutTime.minute || JSON.stringify(previous.payoutTime.monthlyAnchor) !== JSON.stringify(next.payoutTime.monthlyAnchor);
  const before = cycle.rounds.find((round) => round.number === target.roundNumber - 1);
  if (redate && before) {
    const segment = rescheduleFromRound({
      fromRound: target.roundNumber,
      previousPayoutAt: before.payoutAt,
      frequency: next.frequency,
      customPeriodMinutes: next.customPeriodMinutes,
      payoutTime: next.payoutTime,
      now: clock.now()
    });
    for (const round of later) {
      const dates = roundDatesInSegments([segment], round.number);
      await tx2.round.update({
        where: { id: round.id },
        data: { dueAt: dates.dueAt, payoutAt: dates.payoutAt }
      });
      await tx2.obligation.updateMany({
        where: {
          roundId: round.id,
          kind: { in: ["LOAN_INSTALLMENT", "CONTRIBUTION", "SOLIDARITY"] },
          status: "DUE"
        },
        data: { dueAt: dates.dueAt }
      });
    }
  }
  return { effectiveFromRoundId: first.id, effectiveFromRoundNumber: first.number };
}
async function settleExit(tx2, input2) {
  await lockGroup2(tx2, input2.groupId);
  await tx2.$queryRaw`SELECT "id" FROM "Membership" WHERE "id" = ${input2.membershipId}::uuid FOR UPDATE`;
  const payments = await tx2.paymentIntent.count({
    where: {
      groupId: input2.groupId,
      membershipId: input2.membershipId,
      status: { in: [...OPEN_PAYMENT] }
    }
  });
  const disbursements = await tx2.disbursement.count({
    where: {
      groupId: input2.groupId,
      membershipId: input2.membershipId,
      status: { in: [...OPEN_PAYMENT] }
    }
  });
  if (payments + disbursements > 0) throw proposalError("EXIT_PAYMENT_IN_PROGRESS");
  const cycle = await currentCycle(tx2, input2.groupId);
  if (!cycle) return;
  const now = clock.now();
  const leaver = input2.membershipId;
  await tx2.loan.updateMany({
    where: { groupId: input2.groupId, membershipId: leaver, status: "REQUESTED" },
    data: { status: "REJECTED", decidedAt: now }
  });
  const unsent = await tx2.loan.findMany({
    where: {
      groupId: input2.groupId,
      membershipId: leaver,
      status: "APPROVED",
      OR: [{ disbursementId: null }, { disbursement: { status: "FAILED" } }]
    },
    select: { id: true }
  });
  if (unsent.length > 0) {
    const ids = unsent.map((loan) => loan.id);
    await tx2.loan.updateMany({ where: { id: { in: ids } }, data: { status: "EXPIRED" } });
    await tx2.obligation.updateMany({
      where: { loanId: { in: ids }, status: "DUE" },
      data: { status: "CANCELLED" }
    });
  }
  const paying = await tx2.paymentIntent.findMany({
    where: { groupId: input2.groupId, membershipId: leaver, status: { in: [...OPEN_PAYMENT] } },
    select: { obligationIds: true }
  });
  const reserved = new Set(paying.flatMap((intent) => intent.obligationIds));
  const owed = (await tx2.obligation.findMany({
    where: { groupId: input2.groupId, membershipId: leaver, status: "DUE" },
    include: { loan: { select: { status: true, disbursement: { select: { status: true } } } } },
    orderBy: [{ dueAt: "asc" }, { id: "asc" }]
  })).filter((row) => !reserved.has(row.id));
  const inFlight = (row) => row.kind === "LOAN_INSTALLMENT" && (row.loan?.status === "APPROVED" || [...OPEN_PAYMENT].includes(row.loan?.disbursement?.status));
  const debts = owed.filter((row) => DEBT_KINDS.includes(row.kind));
  const paid = await tx2.obligation.findMany({
    where: {
      groupId: input2.groupId,
      membershipId: leaver,
      kind: "CONTRIBUTION",
      status: { in: ["PAID", "SETTLED"] },
      round: { cycleId: cycle.id }
    },
    select: { amount: true }
  });
  const chain = await readChain(tx2, input2.groupId);
  const balances = computeBalances(chain);
  const payable = payableAccount(leaver);
  const members = await tx2.membership.findMany({
    where: { groupId: input2.groupId, status: { in: ["ACTIVE", "LEAVING"] } },
    select: { id: true }
  });
  const active = new Set(members.map((member) => member.id));
  const remaining = [
    ...cycle.rotation.filter((id) => active.has(id) && id !== leaver),
    ...members.map((m) => m.id).filter((id) => !cycle.rotation.includes(id) && id !== leaver)
  ];
  const scheduled = cycle.rounds.filter((round) => round.status === "SCHEDULED");
  const served = cycle.rounds.some(
    (round) => round.beneficiaryMembershipId === leaver && round.status !== "SCHEDULED"
  );
  const result = exitSettlement({
    served,
    contributionsPaidThisCycle: sumFcfa(paid.map((row) => row.amount)),
    availableForLoans: availableForLoans({ summary: summarizeBalances(balances) }),
    leaverPayableBalance: Math.max(0, naturalBalance(payable, balances.get(payable) ?? 0)),
    leaverDebts: debts.filter((row) => row.kind !== "LOAN_INSTALLMENT" && row.dueAt <= now).map((row) => ({
      id: row.id,
      kind: row.kind,
      amount: row.amount,
      dueAt: row.dueAt
    })),
    leaverLoanInstallments: debts.filter((row) => row.kind === "LOAN_INSTALLMENT").map((row) => ({
      id: row.id,
      amount: row.amount,
      dueAt: row.dueAt,
      ...inFlight(row) ? { loanInFlight: true } : {}
    })),
    remainingMembershipIds: remaining,
    nextRoundDueAt: scheduled[0]?.dueAt ?? now,
    now
  });
  if (result.kind === "NOT_SERVED") {
    await tx2.obligation.updateMany({
      where: {
        id: {
          in: owed.filter((row) => ["CONTRIBUTION", "SOLIDARITY", "SHORTFALL_SHARE"].includes(row.kind)).map((row) => row.id)
        },
        status: "DUE"
      },
      data: { status: "CANCELLED" }
    });
    if (result.fromFund > 0) {
      await appendLedgerEntry(tx2, input2.groupId, {
        type: "LEAVER_REFUND",
        occurredAt: now.toISOString(),
        roundId: null,
        membershipId: leaver,
        refType: "Proposal",
        refId: input2.proposalId,
        descriptionFr: "Cotisations rendues au membre sortant",
        descriptionEn: "Contributions returned to the leaving member",
        metadata: { refund: result.refund, shortfall: result.shortfall },
        postings: leaverRefundPostings({ membershipId: leaver, amount: result.fromFund })
      });
    }
    if (result.shortfallShares.length > 0) {
      await tx2.obligation.createMany({
        data: result.shortfallShares.map((share) => ({
          groupId: input2.groupId,
          membershipId: share.membershipId,
          kind: "SHORTFALL_SHARE",
          amount: share.amount,
          dueAt: share.dueAt,
          creditorMembershipId: leaver
        }))
      });
    }
    if (cycle.rotation.includes(leaver)) {
      const order = removeFromRotation(cycle.rotation, leaver);
      await tx2.cycle.update({ where: { id: cycle.id }, data: { rotation: order } });
      const last = scheduled.at(-1);
      for (const round of scheduled) {
        if (round.id === last?.id) continue;
        if (cycle.mode === "FIXED") {
          await tx2.round.update({
            where: { id: round.id },
            data: { beneficiaryMembershipId: order[round.number - 1] ?? null }
          });
        }
      }
      if (last) {
        await tx2.ruleSet.updateMany({
          where: { effectiveFromRoundId: last.id },
          data: { effectiveFromRoundId: null }
        });
        const dependents = await tx2.obligation.count({ where: { roundId: last.id } }) + await tx2.ledgerTransaction.count({ where: { roundId: last.id } });
        if (dependents === 0) {
          await tx2.round.delete({ where: { id: last.id } });
        } else {
          await tx2.obligation.updateMany({
            where: { roundId: last.id, status: "DUE" },
            data: { status: "CANCELLED" }
          });
          await tx2.round.update({
            where: { id: last.id },
            data: { status: "CLOSED", beneficiaryMembershipId: null }
          });
        }
      }
      await appendLedgerEntry(tx2, input2.groupId, {
        type: "EVENT",
        occurredAt: now.toISOString(),
        roundId: null,
        membershipId: null,
        refType: "Proposal",
        refId: input2.proposalId,
        descriptionFr: "Ordre des tours mis \xE0 jour apr\xE8s un d\xE9part",
        descriptionEn: "Round order updated after a member left",
        metadata: {
          event: "ROTATION_CHANGED",
          cycleNumber: cycle.number,
          order,
          proposalId: input2.proposalId
        },
        postings: []
      });
    }
  } else if (scheduled.length > 0) {
    const params = await getCurrentParams(input2.groupId, tx2);
    for (const round of scheduled) {
      const drafts = roundObligations({
        contributionAmount: params.contributionAmount,
        solidarityContribution: params.solidarityContribution,
        round: {
          id: round.id,
          dueAt: round.dueAt,
          beneficiaryMembershipId: round.beneficiaryMembershipId
        },
        activeMembershipIds: [leaver]
      });
      await tx2.obligation.createMany({
        data: drafts.map((draft) => ({
          groupId: input2.groupId,
          membershipId: draft.membershipId,
          kind: draft.kind,
          amount: draft.amount,
          dueAt: draft.dueAt,
          roundId: draft.roundId,
          creditorMembershipId: draft.creditorMembershipId
        }))
      });
    }
  }
  if (result.acceleratedInstallmentIds.length > 0) {
    await tx2.obligation.updateMany({
      where: { id: { in: result.acceleratedInstallmentIds }, status: "DUE" },
      data: { dueAt: now }
    });
  }
  await settleDueDebts(tx2, { groupId: input2.groupId, membershipId: leaver, now });
}

// src/modules/solidarity/solidarity.money.ts
init_src2();
init_env();
init_clock();
init_logger();
init_prisma();
init_dispatch();
init_registry4();
import { randomUUID as randomUUID9 } from "node:crypto";
init_loans_service();
init_rulesets2();
var log14 = componentLogger("solidarity");
var LIVE_SEND = ["CREATED", "PENDING", "EXPIRED", "SUCCESSFUL"];
async function solidarityFund(db, groupId) {
  const [chain, waiting] = await Promise.all([
    readChain(db, groupId),
    db.solidarityRequest.findMany({
      where: { groupId, status: "APPROVED", disbursementId: null },
      select: { amount: true }
    })
  ]);
  return {
    balance: summarizeBalances(computeBalances(chain)).solidarityFund,
    pendingPayouts: sumFcfa(waiting.map((request2) => request2.amount))
  };
}
async function sendSolidarity(tx2, requestId, now) {
  await tx2.$queryRaw`SELECT "id" FROM "SolidarityRequest" WHERE "id" = ${requestId}::uuid FOR UPDATE`;
  const request2 = await tx2.solidarityRequest.findUnique({
    where: { id: requestId },
    include: {
      disbursement: { select: { status: true } },
      recipient: {
        include: {
          user: { include: { paymentNumbers: { where: { activeTo: null }, take: 1 } } }
        }
      }
    }
  });
  if (!request2 || request2.status !== "APPROVED") return null;
  if (request2.disbursement && LIVE_SEND.includes(request2.disbursement.status)) return null;
  await tx2.$queryRaw`SELECT "id" FROM "Group" WHERE "id" = ${request2.groupId}::uuid FOR UPDATE`;
  const group2 = await tx2.group.findUniqueOrThrow({
    where: { id: request2.groupId },
    select: { providerAccount: true }
  });
  const user = request2.recipient.user;
  const number = user.paymentNumbers[0];
  const hadAnotherNumber = number ? await tx2.paymentNumber.count({
    where: { userId: user.id, activeTo: { not: null }, activeFrom: { lte: number.activeFrom } }
  }) > 0 : false;
  const params = await getCurrentParams(request2.groupId, tx2);
  const check3 = await tx2.reconciliationRun.findFirst({
    where: { providerAccount: group2.providerAccount },
    orderBy: { ranAt: "desc" },
    select: { status: true }
  });
  const feeEstimated = scheduleFee(configuredFeeSchedule(), "DISBURSEMENT", request2.amount);
  const fund = summarizeBalances(computeBalances(await readChain(tx2, request2.groupId)));
  const allowed = validateSolidarityDisbursement({
    amount: request2.amount,
    solidarityFundBalance: fund.solidarityFund,
    feeEstimate: feeEstimated,
    hold: activeHold({
      numberChangedAt: hadAnotherNumber ? number?.activeFrom ?? null : null,
      pinResetAt: user.pinResetAt,
      holdHours: params.numberChangeHoldHours,
      now
    }),
    reconciliationStatus: check3?.status ?? null,
    hasActivePaymentNumber: Boolean(number)
  });
  if (!allowed.ok || !["ACTIVE", "LEAVING"].includes(request2.recipient.status)) {
    log14.info(
      { requestId, reason: allowed.ok ? "RECIPIENT_NOT_MEMBER" : allowed.code },
      "solidarity payout waits"
    );
    return null;
  }
  const id = randomUUID9();
  const sent = solidaritySentPostings({ operationId: id, amount: request2.amount, feeEstimated });
  await tx2.disbursement.create({
    data: {
      id,
      groupId: request2.groupId,
      membershipId: request2.recipientMembershipId,
      purpose: "SOLIDARITY",
      // What reaches the recipient: the voted amount less the operator's fee (R4.3).
      amount: sent.metadata.amount,
      feeEstimated,
      phoneSnapshot: number.number,
      provider: getEnv().PAYMENT_PROVIDER,
      status: "CREATED"
    }
  });
  await tx2.solidarityRequest.update({ where: { id: requestId }, data: { disbursementId: id } });
  await appendLedgerEntry(tx2, request2.groupId, {
    type: "DISBURSEMENT_SENT",
    occurredAt: now.toISOString(),
    roundId: null,
    membershipId: request2.recipientMembershipId,
    refType: "Disbursement",
    refId: id,
    descriptionFr: "Soutien de la caisse de secours envoy\xE9",
    descriptionEn: "Solidarity support sent",
    metadata: sent.metadata,
    postings: sent.postings
  });
  return id;
}
var submit = (disbursementId) => dispatchJob(
  "disbursements.submit",
  { disbursementId },
  { jobId: `disbursement-submit-${disbursementId}` }
);
async function paySolidarity(tx2, input2, effects) {
  const disbursementId = await sendSolidarity(tx2, input2.solidarityRequestId, clock.now());
  if (disbursementId && effects) effects.add(() => submit(disbursementId));
}
async function payWaitingSolidarity(now = clock.now()) {
  const waiting = await getPrisma().solidarityRequest.findMany({
    where: { status: "APPROVED" },
    select: { id: true, disbursement: { select: { id: true, status: true, providerRef: true } } },
    orderBy: { createdAt: "asc" },
    take: 100
  });
  let sent = 0;
  for (const request2 of waiting) {
    if (request2.disbursement?.status === "CREATED" && !request2.disbursement.providerRef) {
      await submit(request2.disbursement.id);
      continue;
    }
    const id = await getPrisma().$transaction((tx2) => sendSolidarity(tx2, request2.id, now));
    if (!id) continue;
    await submit(id);
    sent += 1;
  }
  return sent;
}
function registerSolidarityJobs() {
  registerJob({
    name: "solidarity.pay.scan",
    keepNoHistory: true,
    process: async (_job) => {
      await payWaitingSolidarity();
    }
  });
  registerRepeatable({
    id: "solidarity.pay.scan.hourly",
    name: "solidarity.pay.scan",
    pattern: "15 * * * *"
  });
}

