// src/modules/fines/fines.service.ts
init_src2();
init_clock();
init_prisma();
init_src2();
async function assessRoundFines(roundId, now = clock.now()) {
  const db = getPrisma();
  return db.$transaction(async (tx2) => {
    const round = await tx2.round.findUnique({
      where: { id: roundId },
      include: { cycle: { select: { id: true } } }
    });
    if (!round || round.dueAt > now) return 0;
    await tx2.$queryRaw`SELECT "id" FROM "Round" WHERE "id" = ${roundId}::uuid FOR UPDATE`;
    const ruleSet = await tx2.ruleSet.findFirstOrThrow({
      where: { groupId: round.groupId, version: round.ruleSetVersion }
    });
    const params = completeRuleSet(ruleSet.params);
    const valid = validateRuleSet(params);
    if (!valid.ok) throw new Error(`Invalid rule set ${round.ruleSetVersion}: ${valid.code}`);
    const obligations = await tx2.obligation.findMany({
      where: { roundId, kind: { in: ["CONTRIBUTION", "SOLIDARITY"] } },
      select: { id: true, membershipId: true, kind: true, status: true }
    });
    const pending2 = await tx2.paymentIntent.findMany({
      where: {
        groupId: round.groupId,
        OR: [{ status: { in: ["CREATED", "PENDING"] } }, { status: "EXPIRED" }],
        createdAt: { lt: round.dueAt },
        obligationIds: { hasSome: obligations.map((o) => o.id) }
      },
      select: { obligationIds: true }
    });
    const pendingIds = new Set(pending2.flatMap((p) => p.obligationIds));
    const members = await tx2.membership.findMany({
      where: { groupId: round.groupId, status: { in: ["ACTIVE", "LEAVING"] } },
      select: { id: true }
    });
    const standing = members.map((member) => ({
      membershipId: member.id,
      obligations: obligations.filter((o) => o.membershipId === member.id).map((o) => ({
        kind: o.kind,
        status: o.status,
        onTimeIntentInProgress: pendingIds.has(o.id)
      }))
    }));
    const fines2 = roundLateFines({ lateFine: params.lateFine, members: standing });
    let assessed = 0;
    for (const fine of fines2) {
      const prior = await tx2.obligation.findFirst({
        where: {
          groupId: round.groupId,
          roundId,
          membershipId: fine.membershipId,
          kind: "FINE",
          loanId: null
        }
      });
      if (prior) continue;
      const obligation = await tx2.obligation.create({
        data: {
          groupId: round.groupId,
          roundId,
          membershipId: fine.membershipId,
          kind: "FINE",
          amount: fine.amount,
          dueAt: now
        }
      });
      await appendLedgerEntry(tx2, round.groupId, {
        type: "FINE_ASSESSED",
        occurredAt: now.toISOString(),
        roundId,
        membershipId: fine.membershipId,
        refType: "Obligation",
        refId: obligation.id,
        descriptionFr: `Amende de retard, tour ${round.number}`,
        descriptionEn: `Late fine, round ${round.number}`,
        metadata: { obligationId: obligation.id, reason: "ROUND_LATE", roundNumber: round.number },
        postings: fineAssessedPostings({ membershipId: fine.membershipId, amount: fine.amount })
      });
      assessed++;
    }
    const installments = await tx2.obligation.findMany({
      where: { roundId, kind: "LOAN_INSTALLMENT", status: "DUE", dueAt: { lte: now } },
      select: {
        id: true,
        membershipId: true,
        loanId: true,
        amount: true,
        dueAt: true,
        loan: { select: { status: true } }
      }
    });
    if (installments.length > 0) {
      const intents = await tx2.paymentIntent.findMany({
        where: {
          groupId: round.groupId,
          OR: [{ status: { in: ["CREATED", "PENDING"] } }, { status: "EXPIRED" }],
          createdAt: { lt: round.dueAt },
          obligationIds: { hasSome: installments.map((o) => o.id) }
        },
        select: { obligationIds: true }
      });
      const inProgress = new Set(intents.flatMap((p) => p.obligationIds));
      const ledger = await tx2.ledgerTransaction.findMany({
        where: { groupId: round.groupId },
        include: { postings: { select: { account: true, amount: true } } },
        orderBy: { seq: "asc" }
      });
      for (const installment of installments) {
        if (!installment.loanId || inProgress.has(installment.id) || !["DISBURSED", "OVERDUE"].includes(installment.loan?.status ?? ""))
          continue;
        const currentRound2 = await tx2.round.findUnique({
          where: { id: roundId },
          select: { beneficiaryMembershipId: true }
        });
        const lockedPayout = currentRound2?.beneficiaryMembershipId === installment.membershipId ? ledger.filter((entry2) => entry2.roundId === roundId).flatMap((entry2) => entry2.postings).filter(
          (posting) => posting.account === payableAccount(installment.membershipId) && posting.amount < 0
        ).reduce((sum, posting) => sum - posting.amount, 0) : 0;
        const priorDebts = await tx2.obligation.findMany({
          where: {
            membershipId: installment.membershipId,
            status: "DUE",
            dueAt: { lte: installment.dueAt },
            kind: { in: ["BID", "FINE", "CORRECTION", "LOAN_INSTALLMENT"] }
          },
          select: {
            id: true,
            kind: true,
            amount: true,
            dueAt: true,
            loan: { select: { disbursement: { select: { status: true } } } }
          }
        });
        const determination = installmentFine({
          lateFine: params.lateFine,
          installment: {
            id: installment.id,
            amount: installment.amount,
            dueAt: installment.dueAt,
            status: "DUE",
            onTimeIntentInProgress: false
          },
          borrowerIsRoundBeneficiary: currentRound2?.beneficiaryMembershipId === installment.membershipId,
          lockedPayout,
          otherDueDebts: priorDebts.filter((debt) => debt.id !== installment.id).map((debt) => ({
            id: debt.id,
            kind: debt.kind,
            amount: debt.amount,
            dueAt: debt.dueAt,
            loanInFlight: ["CREATED", "PENDING", "EXPIRED"].includes(
              debt.loan?.disbursement?.status ?? ""
            )
          }))
        });
        if (!determination.fined) continue;
        const priorFine = await tx2.obligation.findFirst({
          where: {
            groupId: round.groupId,
            roundId,
            membershipId: installment.membershipId,
            kind: "FINE",
            loanId: installment.loanId
          }
        });
        if (priorFine) continue;
        await tx2.loan.updateMany({
          where: { id: installment.loanId, status: "DISBURSED" },
          data: { status: "OVERDUE" }
        });
        const obligation = await tx2.obligation.create({
          data: {
            groupId: round.groupId,
            roundId,
            membershipId: installment.membershipId,
            loanId: installment.loanId,
            kind: "FINE",
            amount: determination.amount,
            dueAt: now
          }
        });
        await appendLedgerEntry(tx2, round.groupId, {
          type: "FINE_ASSESSED",
          occurredAt: now.toISOString(),
          roundId,
          membershipId: installment.membershipId,
          refType: "Obligation",
          refId: obligation.id,
          descriptionFr: `Amende de remboursement, tour ${round.number}`,
          descriptionEn: `Loan installment fine, round ${round.number}`,
          metadata: {
            obligationId: obligation.id,
            relatedObligationId: installment.id,
            reason: "INSTALLMENT_LATE",
            roundNumber: round.number
          },
          postings: fineAssessedPostings({
            membershipId: installment.membershipId,
            amount: determination.amount
          })
        });
        assessed++;
      }
    }
    return assessed;
  });
}
async function assessDueRoundFines(now = clock.now()) {
  const rounds = await getPrisma().round.findMany({
    where: { dueAt: { lte: now }, status: { in: ["OPEN", "PAYOUT", "CLOSED"] } },
    select: { id: true },
    take: 500,
    orderBy: { dueAt: "asc" }
  });
  let count = 0;
  for (const round of rounds) count += await assessRoundFines(round.id, now);
  return count;
}
async function processFineJob(_job) {
  await assessDueRoundFines();
}

// src/modules/fines/fines.jobs.ts
function registerFineJobs() {
  registerJob({
    name: "fines.assess",
    keepNoHistory: true,
    concurrency: 1,
    process: processFineJob
  });
  registerRepeatable({ id: "fines.assess.scan", name: "fines.assess", pattern: "*/5 * * * *" });
}

// src/modules/reconciliation/reconciliation.routes.ts
init_common2();
import { Router as Router11 } from "express";
import { z as z47 } from "zod";
init_permissions();

// src/modules/reconciliation/reconciliation.service.ts
init_src2();
init_clock();
init_env();
init_logger();
init_prisma();
var log15 = componentLogger("reconciliation");
var LATE_COLLECTION_WINDOW_MS = 24 * 60 * 6e4;
function configuredFeeSchedule2() {
  const configured = getEnv().FEE_SCHEDULE;
  return {
    collection: [
      { upTo: null, fixed: configured.collection, ratePermille: configured.collectionPermille }
    ],
    disbursement: [
      { upTo: null, fixed: configured.disbursement, ratePermille: configured.disbursementPermille }
    ]
  };
}
function mapTransactions(rows) {
  return rows.map((row) => ({
    id: row.id,
    groupId: row.groupId,
    seq: row.seq,
    type: row.type,
    occurredAt: row.occurredAt.toISOString(),
    roundId: row.roundId,
    membershipId: row.membershipId,
    refType: row.refType,
    refId: row.refId,
    descriptionFr: row.descriptionFr,
    descriptionEn: row.descriptionEn,
    metadata: row.metadata,
    postings: row.postings.map((posting) => ({ account: posting.account, amount: posting.amount })),
    prevHash: row.prevHash,
    hash: row.hash
  }));
}
async function loadGroups(providerAccount) {
  return getPrisma().group.findMany({
    where: { providerAccount },
    select: {
      id: true,
      memberships: {
        where: { status: { in: ["ACTIVE", "LEAVING", "INVITED"] } },
        select: { userId: true }
      },
      ledgerTransactions: {
        orderBy: { seq: "asc" },
        include: { postings: true }
      }
    }
  });
}
async function runDailyReconciliation(providerAccount = "default") {
  const db = getPrisma();
  const now = clock.now();
  const groups = await loadGroups(providerAccount);
  const pending2 = await db.paymentIntent.findMany({
    where: {
      group: { providerAccount },
      OR: [
        { status: { in: ["CREATED", "PENDING"] } },
        {
          status: "EXPIRED",
          createdAt: { gt: new Date(now.getTime() - LATE_COLLECTION_WINDOW_MS) }
        }
      ]
    },
    select: { amount: true }
  });
  const transactions = groups.map((group2) => ({
    groupId: group2.id,
    transactions: mapTransactions(group2.ledgerTransactions)
  }));
  let providerBalance = null;
  let providerFailure = null;
  try {
    const balance = await getPaymentProvider().getBalance(providerAccount);
    if (!Number.isSafeInteger(balance.total) || balance.total < 0)
      providerFailure = "INVALID_PROVIDER_BALANCE";
    else providerBalance = balance.total;
  } catch (error) {
    providerFailure = error instanceof Error ? error.name : "PROVIDER_UNAVAILABLE";
    log15.error(
      { providerAccount, errorName: providerFailure },
      "provider balance unavailable during reconciliation"
    );
  }
  const computed = dailyReconciliation({
    groups: transactions,
    providerBalance: providerBalance ?? 0,
    pendingCollections: pending2.map((intent) => intent.amount),
    feeSchedule: configuredFeeSchedule2()
  });
  const status = providerFailure ? "ALERT" : computed.status;
  const differences = computed.difference;
  const details = {
    withdrawalsPaused: status === "ALERT",
    ...providerFailure ? { providerBalanceUnavailable: providerFailure } : {},
    ledgerProblemCount: computed.groups.reduce((count, group2) => count + group2.problems.length, 0),
    reservedShortfall: computed.reservedShortfall,
    inFlightDisbursements: computed.inFlightDisbursements,
    inFlightCollections: computed.inFlightCollections,
    inFlightFeeTolerance: computed.inFlightFeeTolerance,
    groups: computed.groups.map((group2) => ({
      groupId: group2.groupId,
      problems: group2.problems.map(({ seq, code, detail }) => ({ seq, code, detail })),
      reservedShortfall: group2.reservedShortfall,
      coverageGaps: group2.coverageGaps
    }))
  };
  const effects = new AfterCommit();
  const previousRun = await db.reconciliationRun.findFirst({
    where: { providerAccount },
    orderBy: { ranAt: "desc" },
    select: { status: true }
  });
  const run = await db.$transaction(async (tx2) => {
    const saved = await tx2.reconciliationRun.create({
      data: {
        ranAt: now,
        providerAccount,
        providerBalance: providerBalance ?? 0,
        ledgerCash: computed.ledgerCash,
        inFlight: computed.inFlightDisbursements + computed.inFlightCollections,
        difference: differences,
        status,
        // Plain numbers, strings and arrays only: stored as the JSON it already is.
        details: JSON.parse(JSON.stringify(details))
      }
    });
    if (status === "ALERT" && previousRun?.status !== "ALERT") {
      const alertBody = providerFailure ? {
        fr: "La v\xE9rification de la caisse ne peut pas lire la balance de l\u2019op\xE9rateur. Les retraits et versements sont suspendus jusqu\u2019au r\xE9tablissement du service.",
        en: "The caisse check cannot read the provider balance. Withdrawals and disbursements are paused until the service recovers."
      } : computed.reservedShortfall > 0 ? {
        fr: "La caisse ne couvre pas tout l\u2019argent r\xE9serv\xE9 aux membres. Les retraits et versements sont suspendus jusqu\u2019\xE0 ce que la couverture soit r\xE9tablie.",
        en: "The caisse does not cover all money reserved for members. Withdrawals and disbursements are paused until coverage is restored."
      } : computed.groups.some((group2) => group2.problems.length > 0) ? {
        fr: "La v\xE9rification a trouv\xE9 une anomalie dans le registre. Les retraits et versements sont suspendus jusqu\u2019\xE0 sa r\xE9solution.",
        en: "The check found an inconsistency in the records. Withdrawals and disbursements are paused until it is resolved."
      } : {
        fr: "La balance de l\u2019op\xE9rateur ne correspond pas au registre, m\xEAme en tenant compte des op\xE9rations en cours. Les retraits et versements sont suspendus jusqu\u2019\xE0 la r\xE9solution de l\u2019\xE9cart.",
        en: "The provider balance does not match the records, even after accounting for operations in progress. Withdrawals and disbursements are paused until the difference is resolved."
      };
      const memberNotices = groups.flatMap(
        (group2) => group2.memberships.map((membership) => ({
          userId: membership.userId,
          groupId: group2.id,
          category: "SECURITY",
          title: { fr: "V\xE9rification de la caisse", en: "Caisse check" },
          body: alertBody,
          deepLink: "/caisse"
        }))
      );
      await createNotifications(memberNotices, effects, tx2);
    }
    return saved;
  });
  await effects.run();
  return run;
}
async function runAllDailyReconciliations() {
  const accounts = await getPrisma().group.findMany({
    distinct: ["providerAccount"],
    select: { providerAccount: true }
  });
  if (accounts.length === 0) return [await runDailyReconciliation("default")];
  const runs = [];
  for (const { providerAccount } of accounts)
    runs.push(await runDailyReconciliation(providerAccount));
  return runs;
}

