// src/modules/bids/bids.service.ts
async function bidContext(db, groupId, roundId, userId) {
  const round = await db.round.findFirst({
    where: { id: roundId, groupId },
    include: {
      cycle: {
        select: {
          number: true,
          mode: true,
          rotation: true,
          rounds: {
            orderBy: { number: "asc" },
            select: { id: true, number: true, beneficiaryMembershipId: true }
          }
        }
      }
    }
  });
  if (!round) throw bidError("ROUND_NOT_FOUND");
  const ruleSet = await db.ruleSet.findFirstOrThrow({
    where: { groupId, version: round.ruleSetVersion }
  });
  const params = completeRuleSet(ruleSet.params);
  const valid = validateRuleSet(params);
  if (!valid.ok) throw new Error(`Invalid rule set ${round.ruleSetVersion}: ${valid.code}`);
  const access = await authorizeGroup(userId, groupId, "group.bids.place", db);
  const previous = round.cycle.rounds.filter((r) => r.number < round.number);
  const eligible = biddingEligible({
    activeMembershipIds: round.cycle.rotation,
    servedMembershipIds: previous.flatMap(
      (r) => r.beneficiaryMembershipId ? [r.beneficiaryMembershipId] : []
    )
  });
  const current = await db.bid.findUnique({
    where: { roundId_membershipId: { roundId, membershipId: access.membership.id } }
  });
  return { round, params, access, eligible, current };
}
async function prepareBid(userId, groupId, roundId, amount, now = clock.now(), db = getPrisma()) {
  const context = await bidContext(db, groupId, roundId, userId);
  const check3 = validateBid({
    rotationMode: context.params.rotationMode,
    membershipId: context.access.membership.id,
    eligibleMembershipIds: context.eligible,
    amount,
    minBid: context.params.minBid,
    currentBid: context.current ? { amount: context.current.amount } : null,
    now,
    closesAt: context.round.dueAt
  });
  if (!check3.ok) throw bidError("BID_NOT_AVAILABLE");
  return { ...context, action: check3.action, amount };
}
async function placeBid(actor, groupId, roundId, amount, origin = "UI") {
  return createPendingAction({
    userId: actor.userId,
    groupId,
    lang: actor.lang,
    origin,
    type: "PLACE_BID",
    args: { groupId, roundId, amount }
  });
}
async function readBids(userId, groupId, roundId, now = clock.now()) {
  const access = await authorizeGroup(userId, groupId, "group.bids.read");
  const round = await getPrisma().round.findFirst({
    where: { id: roundId, groupId },
    select: { id: true, number: true, dueAt: true, beneficiaryMembershipId: true }
  });
  if (!round) throw bidError("ROUND_NOT_FOUND");
  const [count, mine] = await Promise.all([
    getPrisma().bid.count({ where: { roundId } }),
    getPrisma().bid.findUnique({
      where: { roundId_membershipId: { roundId, membershipId: access.membership.id } },
      select: { amount: true, placedAt: true, updatedAt: true }
    })
  ]);
  const closesAt = { fr: formatDateTime(round.dueAt, "fr"), en: formatDateTime(round.dueAt, "en") };
  if (now < round.dueAt) return { round: round.number, closesAt, count, mine, bids: null };
  const bids = await getPrisma().bid.findMany({
    where: { roundId },
    orderBy: [{ amount: "desc" }, { updatedAt: "asc" }],
    include: { membership: { select: { id: true, user: { select: { name: true } } } } }
  });
  const winner = bidWinner(
    bids.map((b) => ({ membershipId: b.membershipId, amount: b.amount, reachedAt: b.updatedAt }))
  );
  return {
    round: round.number,
    closesAt,
    count,
    mine,
    winnerMembershipId: winner?.membershipId ?? null,
    bids: bids.map((b) => ({
      membershipId: b.membershipId,
      name: b.membership.user.name,
      amount: b.amount,
      reachedAt: b.updatedAt
    }))
  };
}

// src/modules/bids/bids.actions.ts
var argsSchema2 = z48.strictObject({
  groupId: z48.string().uuid(),
  roundId: z48.string().uuid(),
  amount: z48.number().int().positive()
});
var placeBidHandler = defineActionHandler({
  type: "PLACE_BID",
  level: "L1",
  args: argsSchema2,
  async prepare(ctx, args5) {
    const prepared2 = await prepareBid(
      ctx.userId,
      args5.groupId,
      args5.roundId,
      args5.amount,
      ctx.now,
      ctx.db
    );
    const raised = prepared2.action === "RAISE";
    return {
      title: raised ? ui((c) => c.confirmation.actions.raiseBid.title) : ui((c) => c.confirmation.actions.placeBid.title, { round: prepared2.round.number }),
      lines: [{ label: ui((c) => c.confirmation.lines.bidAmount), amount: args5.amount }],
      total: args5.amount,
      notes: [
        ui((c) => c.confirmation.notes.bidSealed, {
          date: {
            fr: formatDateTime(prepared2.round.dueAt, "fr"),
            en: formatDateTime(prepared2.round.dueAt, "en")
          }
        })
      ],
      confirmLabel: raised ? ui((c) => c.confirmation.actions.raiseBid.button, {
        amount: { fr: formatXAF(args5.amount, "fr"), en: formatXAF(args5.amount, "en") }
      }) : ui((c) => c.confirmation.actions.placeBid.button, {
        amount: { fr: formatXAF(args5.amount, "fr"), en: formatXAF(args5.amount, "en") }
      })
    };
  },
  async execute(ctx, args5) {
    const prepared2 = await prepareBid(
      ctx.userId,
      args5.groupId,
      args5.roundId,
      args5.amount,
      ctx.now,
      ctx.db
    );
    if (prepared2.action === "RAISE") {
      await ctx.db.bid.update({
        where: {
          roundId_membershipId: {
            roundId: args5.roundId,
            membershipId: prepared2.access.membership.id
          }
        },
        data: { amount: args5.amount, updatedAt: ctx.now }
      });
    } else if (!prepared2.current) {
      await ctx.db.bid.create({
        data: {
          roundId: args5.roundId,
          membershipId: prepared2.access.membership.id,
          amount: args5.amount,
          placedAt: ctx.now,
          updatedAt: ctx.now
        }
      });
    } else {
      throw bidError("BID_ACTION_CHANGED");
    }
    return {
      outcome: "done",
      resultRef: args5.roundId,
      summary: ui((c) => c.confirmation.actions.placeBid.done)
    };
  }
});

