// src/modules/bids/bids.close.ts
init_src2();
init_clock();
init_prisma();
init_registry4();
function eventText(event) {
  return event.event === "BIDS_PUBLISHED" ? {
    descriptionFr: `Ench\xE8res publi\xE9es, tour ${event.roundNumber}`,
    descriptionEn: `Bids published, round ${event.roundNumber}`
  } : {
    descriptionFr: `Tirage du b\xE9n\xE9ficiaire, tour ${event.roundNumber}`,
    descriptionEn: `Beneficiary draw, round ${event.roundNumber}`
  };
}
async function closeBidding2(roundId, now = clock.now()) {
  const db = getPrisma();
  return db.$transaction(async (tx2) => {
    await tx2.$queryRaw`SELECT "id" FROM "Round" WHERE "id" = ${roundId}::uuid FOR UPDATE`;
    const round = await tx2.round.findUnique({
      where: { id: roundId },
      include: {
        cycle: {
          select: {
            number: true,
            mode: true,
            rotation: true,
            rounds: {
              orderBy: { number: "asc" },
              select: { number: true, beneficiaryMembershipId: true }
            }
          }
        }
      }
    });
    if (!round || round.cycle.mode !== "BIDDING" || round.dueAt > now || round.beneficiaryMembershipId)
      return false;
    const served = round.cycle.rounds.filter((item) => item.number < round.number).flatMap((item) => item.beneficiaryMembershipId ? [item.beneficiaryMembershipId] : []);
    const eligible = round.cycle.rotation.filter((membershipId) => !served.includes(membershipId));
    if (eligible.length === 0) return false;
    const bids = await tx2.bid.findMany({
      where: { roundId, membershipId: { in: eligible } },
      select: { membershipId: true, amount: true, updatedAt: true }
    });
    const head = await ledgerHead(tx2, round.groupId);
    const outcome = closeBidding({
      groupId: round.groupId,
      cycleNumber: round.cycle.number,
      roundNumber: round.number,
      roundId: round.id,
      latestLedgerHash: head?.hash ?? genesisHash(round.groupId),
      eligibleMembershipIds: eligible,
      bids: bids.map((bid) => ({
        membershipId: bid.membershipId,
        amount: bid.amount,
        reachedAt: bid.updatedAt
      }))
    });
    const beneficiaryMembershipId = outcome.beneficiaryMembershipId;
    if (outcome.outcome === "WINNING_BID") {
      const event = {
        event: "BIDS_PUBLISHED",
        cycleNumber: round.cycle.number,
        roundNumber: round.number,
        roundId: round.id,
        beneficiaryMembershipId,
        bids: outcome.publishedBids
      };
      const text = eventText(event);
      await appendLedgerEntry(tx2, round.groupId, {
        type: "EVENT",
        occurredAt: now.toISOString(),
        roundId: round.id,
        membershipId: beneficiaryMembershipId,
        refType: "Round",
        refId: round.id,
        ...text,
        metadata: event,
        postings: []
      });
      if (outcome.amount > 0) {
        const debt = await tx2.obligation.create({
          data: {
            groupId: round.groupId,
            membershipId: beneficiaryMembershipId,
            kind: "BID",
            amount: outcome.amount,
            dueAt: round.payoutAt,
            roundId
          }
        });
        await appendLedgerEntry(tx2, round.groupId, {
          type: "BID_ASSESSED",
          occurredAt: now.toISOString(),
          roundId: round.id,
          membershipId: beneficiaryMembershipId,
          refType: "Obligation",
          refId: debt.id,
          descriptionFr: `Ench\xE8re gagnante, tour ${round.number}`,
          descriptionEn: `Winning bid, round ${round.number}`,
          metadata: { obligationId: debt.id, amount: outcome.amount, roundNumber: round.number },
          postings: bidAssessedPostings({
            membershipId: beneficiaryMembershipId,
            amount: outcome.amount
          })
        });
      }
    } else if (outcome.outcome === "DRAW") {
      const text = eventText(outcome.event);
      await appendLedgerEntry(tx2, round.groupId, {
        type: "EVENT",
        occurredAt: now.toISOString(),
        roundId: round.id,
        membershipId: beneficiaryMembershipId,
        refType: "Round",
        refId: round.id,
        ...text,
        metadata: outcome.event,
        postings: []
      });
    }
    const assigned = await tx2.round.updateMany({
      where: { id: round.id, beneficiaryMembershipId: null, status: "OPEN" },
      data: { beneficiaryMembershipId }
    });
    if (assigned.count !== 1) return false;
    const entries2 = await tx2.ledgerTransaction.findMany({
      where: { groupId: round.groupId },
      include: { postings: { select: { account: true, amount: true } } },
      orderBy: { seq: "asc" }
    });
    const account = potAccount(round.id);
    const raw3 = entries2.flatMap((entry2) => entry2.postings).filter((posting) => posting.account === account).reduce((sum, posting) => sum + posting.amount, 0);
    const pot = naturalBalance(account, raw3);
    if (pot > 0) {
      await appendLedgerEntry(tx2, round.groupId, {
        type: "POT_ASSIGNED",
        occurredAt: now.toISOString(),
        roundId: round.id,
        membershipId: beneficiaryMembershipId,
        refType: "Round",
        refId: round.id,
        descriptionFr: `Pot attribu\xE9, tour ${round.number}`,
        descriptionEn: `Pot assigned, round ${round.number}`,
        metadata: { beneficiaryMembershipId, amount: pot },
        postings: potAssignedPostings({ roundId: round.id, beneficiaryMembershipId, amount: pot })
      });
    }
    return true;
  });
}
async function closeDueBidding(now = clock.now()) {
  const due = await getPrisma().round.findMany({
    where: {
      status: "OPEN",
      beneficiaryMembershipId: null,
      dueAt: { lte: now },
      cycle: { mode: "BIDDING" }
    },
    select: { id: true },
    orderBy: { dueAt: "asc" },
    take: 100
  });
  let closed = 0;
  for (const round of due) if (await closeBidding2(round.id, now)) closed += 1;
  return closed;
}
function registerBiddingJobs() {
  registerJob({
    name: "bidding.close",
    keepNoHistory: true,
    process: async (_job) => {
      await closeDueBidding();
    }
  });
  registerRepeatable({ id: "bidding.close.scan", name: "bidding.close", pattern: "*/5 * * * *" });
}

