// src/agent/tools/specs/index.ts
var SPECS = { ...readingSpecs, ...preferenceSpecs, ...actionSpecs };
var ALL_SPECS = Object.values(SPECS);

// src/agent/history.ts
var PAGE = 50;
function cursor(before) {
  return before ? { createdAt: { lt: new Date(before) } } : {};
}
function toAgentMessage(row, lang) {
  if (row.role === "tool") {
    if (row.toolName !== EVENT_TOOL) return null;
    const event = readEvent(row.content);
    if (!event) return null;
    return {
      id: row.id,
      role: "event",
      text: event.text[lang],
      fromGroup: false,
      event: {
        pendingActionId: event.pendingActionId,
        status: event.status
      },
      createdAt: iso(row.createdAt)
    };
  }
  return {
    id: row.id,
    role: row.role,
    text: row.content,
    fromGroup: row.role === "user" && row.toolName === FROM_GROUP,
    event: null,
    createdAt: iso(row.createdAt)
  };
}
var ACTION_STATUS = {
  PENDING: "prepared",
  CONFIRMED: "confirmed",
  DONE: "done",
  CANCELLED: "cancelled",
  EXPIRED: "expired",
  FAILED: "failed"
};
function pendingIdOf(content) {
  try {
    const id = JSON.parse(content).pendingActionId;
    return typeof id === "string" ? id : null;
  } catch {
    return null;
  }
}
async function listAgentHistory(userId, query2) {
  const db = getPrisma();
  const limit = query2.limit ?? PAGE;
  const rows = await db.agentMessage.findMany({
    where: {
      role: "tool",
      NOT: { toolName: EVENT_TOOL },
      conversation: { userId },
      ...cursor(query2.before)
    },
    orderBy: { createdAt: "desc" },
    take: limit + 1
  });
  const page = rows.slice(0, limit);
  const ids = page.flatMap((r) => {
    const id = pendingIdOf(r.content);
    return id ? [id] : [];
  });
  const actions = ids.length ? await db.pendingAction.findMany({
    where: { id: { in: ids }, userId },
    select: { id: true, status: true }
  }) : [];
  const statusById = new Map(actions.map((a) => [a.id, a.status]));
  const items = page.map((row) => {
    const pendingActionId = pendingIdOf(row.content);
    const spec = SPECS[row.toolName ?? ""];
    let status = "looked";
    if (row.toolStatus === "REFUSED") status = "refused";
    else if (row.toolStatus !== "OK") status = "failed";
    else if (pendingActionId) status = ACTION_STATUS[statusById.get(pendingActionId) ?? "PENDING"];
    else if (spec && spec.level !== "L0") status = "prepared";
    return {
      id: row.id,
      tool: row.toolName ?? "",
      status,
      pendingActionId,
      createdAt: iso(row.createdAt)
    };
  });
  return { items, nextBefore: rows.length > limit ? iso(page[page.length - 1].createdAt) : null };
}

