async function guardedTurn(deps, input2) {
  try {
    return await runTurn(deps, input2);
  } catch (error) {
    if (isLlmError(error))
      throw agentError("AGENT_UNAVAILABLE", { details: { reason: error.code } });
    throw error;
  }
}
async function toTurnDto(ctx, conversation, result) {
  const actions = await Promise.all(
    result.pendingActionIds.map(
      async (id) => toPendingAction(await getOwnPendingAction(ctx.userId, id))
    )
  );
  return {
    id: ctx.turnId,
    conversationId: conversation.id,
    reply: toAgentMessage(result.replyMessage, ctx.lang),
    actions,
    cards: result.cards,
    toolCalls: result.runs.map((r) => ({ name: r.name, status: r.status })),
    activeGroupId: result.activeGroupId !== void 0 ? result.activeGroupId : conversation.groupId,
    language: ctx.lang
  };
}
async function privateTurn(ctx, conversation, text, options = {}) {
  const deps = productionDeps(ctx);
  const result = await guardedTurn(deps, { ctx, conversation, text, ...options });
  if (result.activeGroupId !== void 0 && result.activeGroupId !== conversation.groupId) {
    await dbConversationStore.setGroup(conversation.id, result.activeGroupId);
    conversation.groupId = result.activeGroupId;
  }
  const dto2 = await toTurnDto(ctx, conversation, result);
  emitAgent(ctx.userId, "agent.done", dto2);
  return dto2;
}

