// src/agent/runtime/personal.ts
var MENTION = /@njangi\b/giu;
var FIRST_PERSON_FR = /(^|[^\p{L}])((je|moi|mon|ma|mes)(?=[^\p{L}]|$)|[jm]['’])/iu;
var FIRST_PERSON_EN = /(^|[^\p{L}])((i|me|my|mine)(?=[^\p{L}]|$)|i['’])/iu;
var PERSONAL_TOPIC = /(dois|doit|dette|amende|pr[eê]t|tour|argent|solde|cotisation|pay[ée]|paie|retir|num[ée]ro|relev[ée]|vote|owe|debt|fine|loan|turn|money|balance|paid|pay|withdraw|number|statement)/iu;
var ACTION_VERB = /^(paie|payer|paye|retire|retirer|vote|votez|emprunte|emprunter|change|changer|ajoute|ajouter|propose|proposer|supprime|annule|mise|miser|envoie|demande|pay|withdraw|vote|borrow|change|add|propose|delete|cancel|bid|send|request)(?=[^\p{L}]|$)/iu;
function looksPersonal(text) {
  const cleaned = text.replace(MENTION, " ").trim();
  if (ACTION_VERB.test(cleaned)) return true;
  const firstPerson = FIRST_PERSON_FR.test(cleaned) || FIRST_PERSON_EN.test(cleaned);
  return firstPerson && PERSONAL_TOPIC.test(cleaned);
}

// src/agent/service/group.ts
var log21 = componentLogger("agent");
var LEASE_WAIT_MS = 5e3;
async function authorActor(userId) {
  const self = await getSelfSource(userId);
  return { userId, lang: self.user.language, sessionId: "group-mention", client: "mobile" };
}
function privateReplyText(ctx) {
  return bilingual(agentTexts.privateReply, { name: ctx.firstName })[ctx.lang];
}
async function groupAnswer(ctx, text) {
  if (looksPersonal(text)) return { text: privateReplyText(ctx), privately: true };
  const conversation = await dbConversationStore.open({
    userId: ctx.userId,
    channel: "GROUP",
    groupId: ctx.groupId
  });
  const result = await guardedTurn(productionDeps(ctx), { ctx, conversation, text });
  if (result.privateReply) return { text: privateReplyText(ctx), privately: true };
  return { text: result.reply, privately: false };
}
var GROUP_MENTION_JOB = "agent.groupMention";
async function onGroupMention(mention) {
  if (!agentPorts().chat || !agentConfig().configured) return;
  if (currentJobScheduler() === scheduleAt) {
    await runAsSystem(() => answerGroupMention(mention));
    return;
  }
  await dispatchJob(GROUP_MENTION_JOB, { ...mention }, { jobId: mention.messageId });
}
async function answerGroupMention(mention) {
  const chat = agentPorts().chat;
  if (!chat || !agentConfig().configured) return;
  const text = await chat.mentionText({
    groupId: mention.groupId,
    messageId: mention.messageId,
    userId: mention.authorUserId
  });
  if (!text || !await tryConsumeAgentMessage(mention.authorUserId)) return;
  const actor = await authorActor(mention.authorUserId);
  await withTurnLease(
    actor.userId,
    async () => {
      const ctx = await buildCtx(actor, { groupId: mention.groupId, channel: "GROUP", text });
      const answer = await groupAnswer(ctx, text);
      await chat.postAgentReply({
        groupId: mention.groupId,
        text: answer.text,
        replyToMessageId: mention.messageId
      });
      if (!answer.privately) return;
      const privateCtx = await buildCtx(actor, {
        groupId: mention.groupId,
        channel: "PRIVATE",
        text
      });
      const conversation = await dbConversationStore.open({
        userId: actor.userId,
        channel: "PRIVATE",
        groupId: mention.groupId
      });
      if (conversation.groupId !== mention.groupId) {
        await dbConversationStore.setGroup(conversation.id, mention.groupId);
        conversation.groupId = mention.groupId;
      }
      await privateTurn(privateCtx, conversation, text, { fromGroup: true });
    },
    { waitMs: LEASE_WAIT_MS }
  ).catch((error) => {
    log21.error(
      { errorName: error instanceof Error ? error.name : "unknown" },
      "group mention failed"
    );
  });
}

